<?php
require_once dirname(__DIR__).'/src/db.php';
try{require_disposable_test_profile();}catch(Throwable $e){fwrite(STDERR,"REFUSED: ".$e->getMessage()."\n");exit(2);}
$base=rtrim($argv[1]??'','/');$token=(string)($argv[2]??'');$host=strtolower((string)parse_url($base,PHP_URL_HOST));if(!$base||!in_array($host,['127.0.0.1','localhost','::1'],true)){fwrite(STDERR,"REFUSED: bench integration must use the loopback scratch server.\n");exit(2);}
$modeFile=mode_file_path();$oldMode=file_get_contents($modeFile);$pdo=db();$failed=false;
function bench_check(bool $ok,string $label): void {if(!$ok)throw new RuntimeException($label);echo "PASS $label\n";}
function bench_api(string $method,string $path,?array $payload=null,string $token=''): array {$headers="Content-Type: application/json\r\n".(getenv('TRAILWATCH_TEST_SESSION_COOKIE')?"Cookie: ".getenv('TRAILWATCH_TEST_SESSION_COOKIE')."\r\nX-CSRF-Token: ".getenv('TRAILWATCH_TEST_CSRF_TOKEN')."\r\n":'');if($token!=='')$headers.="X-Bridge-Token: $token\r\n";$ctx=stream_context_create(['http'=>['method'=>$method,'header'=>$headers,'content'=>$payload===null?'':json_encode($payload,JSON_THROW_ON_ERROR),'ignore_errors'=>true,'timeout'=>8]]);$body=@file_get_contents($GLOBALS['base'].$path,false,$ctx);$line=$http_response_header[0]??'HTTP/1.1 500';return ['status'=>(int)substr($line,9,3),'body'=>is_string($body)?json_decode($body,true):null];}
function bench_expect(int $code,array $result,string $label): array {if($result['status']!==$code)throw new RuntimeException("$label expected HTTP $code, got {$result['status']} ".json_encode($result['body']));echo "PASS $label HTTP $code\n";return$result['body']??[];}
function bench_sequence(PDO $pdo,int $hiker,string $site): int {$q=$pdo->prepare('SELECT sequence_number FROM uplink_packets WHERE hiker_node_id=? AND site_id=?');$q->execute([$hiker,$site]);$used=array_fill_keys(array_map('intval',$q->fetchAll(PDO::FETCH_COLUMN)),true);for($i=65535;$i>=0;$i--)if(!isset($used[$i]))return$i;throw new RuntimeException('No free sequence number');}
try{
    file_put_contents($modeFile,json_encode(['mode'=>'LIVE']));
    $status=bench_expect(200,bench_api('GET','/api/status'),'LIVE scratch status');bench_check(($status['test_database']??false)&&($status['active_mode']??'')==='LIVE','LIVE endpoint is connected only to the disposable scratch database');
    bench_expect(200,bench_api('POST','/api/settings/site',['site_id'=>'pup']),'select PUP in scratch profile');
    bench_expect(201,bench_api('POST','/api/test-sessions/start',['label'=>'BENCH scratch session','phase'=>'PHASE1','design'=>'A','tester_code'=>'SCRATCH','test_point'=>'PUP']),'start LIVE scratch ingest session');
    bench_expect(200,bench_api('POST','/api/settings/phase-mode',['phase_mode'=>'PHASE1']),'set Phase 1 for scratch fixtures');
    $h=$pdo->prepare('SELECT id FROM hiker_nodes WHERE node_id=?');$h->execute(['H1']);$hiker=(int)$h->fetchColumn();if(!$hiker)throw new RuntimeException('seeded H1 is required');
    $benchBefore=bench_expect(200,bench_api('GET','/api/settings/bench-session'),'read initial bench setting');bench_check(empty($benchBefore['enabled']),'bench session starts OFF in the scratch profile');
    $auditBefore=(int)$pdo->query("SELECT COUNT(*) FROM operator_actions WHERE action_type IN ('BENCH_SESSION_ENABLED','BENCH_SESSION_DISABLED')")->fetchColumn();
    bench_expect(200,bench_api('POST','/api/settings/bench-session',['enabled'=>true]),'turn bench session ON');
    $summaryBefore=bench_expect(200,bench_api('GET','/api/research/summary'),'read summary before BENCH uplink')['summary'];
    $seqBench=bench_sequence($pdo,$hiker,'pup');$packet=['uplink'=>['node_id'=>'H1','sequence_number'=>$seqBench,'latitude'=>14.5981,'longitude'=>121.0120,'gps_accuracy_m'=>5,'satellite_count'=>8,'battery_level'=>88,'flags'=>['link_lost'=>false,'low_battery'=>false,'emergency'=>false,'turn_back_received'=>false,'test_mode'=>false]],'reception'=>['base_id'=>'BASE','path_type'=>'DIRECT']];
    $ingest=bench_expect(201,bench_api('POST','/api/bridge/ingest',$packet,$token),'ingest while bench session ON');$packetId=(int)$ingest['packet_id'];bench_check(!empty($ingest['is_bench']),'LIVE session marks new packet BENCH');
    $summaryAfter=bench_expect(200,bench_api('GET','/api/research/summary'),'read summary after BENCH uplink')['summary'];bench_check((int)$summaryAfter['packet_count']===(int)$summaryBefore['packet_count']&&(int)$summaryAfter['excluded_packet_count']===(int)$summaryBefore['excluded_packet_count']+1,'BENCH packet is excluded while REAL packet counts stay unchanged');
    bench_check((int)$summaryAfter['excluded_command_count']===(int)$summaryBefore['excluded_command_count']+1,'command from BENCH uplink is excluded from research summary');
    $logs=bench_expect(200,bench_api('GET','/api/logs/packets?node_id=H1&limit=200'),'read packet log source labels');$logRow=null;foreach($logs['packets']??[] as $row)if((int)$row['sequence_number']===$seqBench){$logRow=$row;break;}bench_check(($logRow['source']??'')==='BENCH'&&(int)($logRow['is_bench']??0)===1,'packet log labels BENCH source');
    $csvCtx=stream_context_create(['http'=>['header'=>"Cookie: ".getenv('TRAILWATCH_TEST_SESSION_COOKIE')."\r\n",'ignore_errors'=>true]]);$csv=@file_get_contents($base.'/api/export.csv?type=packets',false,$csvCtx);$csvBench=false;if(is_string($csv)){foreach(preg_split('/\r?\n/',$csv) as $line){$cells=str_getcsv($line);if(($cells[1]??'')==='H1'&&(string)($cells[2]??'')===(string)$seqBench&&($cells[27]??'')==='BENCH'){$csvBench=true;break;}}}bench_check($csvBench,'packet CSV labels BENCH source');
    bench_expect(200,bench_api('POST','/api/settings/bench-session',['enabled'=>false]),'turn bench session OFF');
    $seqReal=bench_sequence($pdo,$hiker,'pup');$packet['uplink']['sequence_number']=$seqReal;$real=bench_expect(201,bench_api('POST','/api/bridge/ingest',$packet,$token),'ingest after bench session OFF');bench_check(empty($real['is_bench']),'switch OFF returns new unflagged LIVE uplinks to REAL');
    $realLog=bench_expect(200,bench_api('GET','/api/logs/packets?node_id=H1&limit=200'),'read packet log after bench session OFF');$realRow=null;foreach($realLog['packets']??[] as $row)if((int)$row['sequence_number']===$seqReal){$realRow=$row;break;}bench_check(($realRow['source']??'')==='REAL','switch OFF labels the next unflagged LIVE packet REAL');
    $summaryReal=bench_expect(200,bench_api('GET','/api/research/summary'),'read summary after REAL uplink')['summary'];bench_check((int)$summaryReal['packet_count']===(int)$summaryAfter['packet_count']+1,'REAL packet remains counted in research summary');
    $now=time();$from=gmdate('Y-m-d H:i:s',$now-3600);$to=gmdate('Y-m-d H:i:s',$now+3600);$insert=$pdo->prepare("INSERT INTO uplink_packets(hiker_node_id,site_id,sequence_number,latitude,longitude,flags_json,classification,received_at,test_mode,is_demo,is_rehearsal,is_bench) VALUES(?,'pup',?,14.5981,121.0120,?,'UNCLASSIFIED',?,?,?,?,0)");$fixtures=[];
    foreach([['REAL',0,0,0,'{}'],['DEMO',0,1,0,'{}'],['REHEARSAL',0,0,1,'{}'],['TEST',1,0,0,'{}'],['JSON_TEST',0,0,0,'{"test_mode":true}']] as $fixture){$seq=bench_sequence($pdo,$hiker,'pup');[$label,$test,$demo,$rehearsal,$flags]=$fixture;$insert->execute([$hiker,$seq,$flags,$now?gmdate('Y-m-d H:i:s',$now):gmdate('Y-m-d H:i:s'),$test,$demo,$rehearsal]);$fixtures[$label]=['id'=>(int)$pdo->lastInsertId(),'sequence'=>$seq];}
    $fromValue=gmdate('Y-m-d\TH:i',$now-3600);$toValue=gmdate('Y-m-d\TH:i',$now+3600);$range=bench_expect(200,bench_api('POST','/api/packets/mark-bench',['site_id'=>'pup','node_id'=>'H1','from'=>$fromValue,'to'=>$toValue,'confirmation'=>'MARK BENCH']),'mark existing packet range BENCH');
    $q=$pdo->prepare('SELECT is_bench FROM uplink_packets WHERE id=?');$q->execute([$fixtures['REAL']['id']]);$realMarked=(int)$q->fetchColumn();bench_check($realMarked===1&&(int)$range['updated_packet_count']>=2,'range action marks unflagged REAL packets BENCH');
    $protected=$pdo->prepare('SELECT is_bench FROM uplink_packets WHERE id=?');foreach(['DEMO','REHEARSAL','TEST','JSON_TEST'] as $label){$protected->execute([$fixtures[$label]['id']]);$value=(int)$protected->fetchColumn();bench_check($value===0,"range action preserves protected $label packet");}
    $q=$pdo->prepare("SELECT COUNT(*) FROM operator_actions WHERE action_type='PACKET_RANGE_MARKED_BENCH'");$q->execute();bench_check((int)$q->fetchColumn()===1,'range classification creates one operator audit record');
    $q=$pdo->prepare("SELECT COUNT(*) FROM operator_actions WHERE action_type IN ('BENCH_SESSION_ENABLED','BENCH_SESSION_DISABLED')");$q->execute();bench_check((int)$q->fetchColumn()===$auditBefore+2,'both bench session switch transitions are audited');
    bench_expect(400,bench_api('POST','/api/packets/mark-bench',['site_id'=>'pup','node_id'=>'H1','from'=>$fromValue,'to'=>$toValue,'confirmation'=>'wrong']),'range action requires typed confirmation');
    echo "PASS BENCH scratch integration complete; no LIVE database was accessed.\n";
}catch(Throwable $e){fwrite(STDERR,'FAIL '.$e->getMessage()."\n");$failed=true;}
finally{file_put_contents($modeFile,$oldMode===false?'{}':$oldMode);}
if($failed)exit(1);
